                    @LE.le Real Real.instLE
                      (@RiffleUpperV2.conditionalExpect Ω inst P
                        (fun (ω : Ω) =>
                          @Nat.cast Real Real.instNatCast
                            (@HSub.hSub Nat Nat Nat (@instHSub Nat instSubNat) (X m ω) (X i ω)))
                        fun (ω : Ω) => @Eq H (h i ω) (h i a))
                      γ) →
            ∀ (r i : Nat),
