                            (@Nat.cast Real Real.instNatCast
                              ((@HSub.hSub Nat Nat Nat (@instHSub Nat instSubNat) (X m ω) (X i ω)).choose r)))
                        (@HMul.hMul Real Real Real (@instHMul Real Real.instMul)
                          (@HPow.hPow Real Nat Real
                            (@instHPow Real Nat (@NPow.toPow Real (@Monoid.toNPow Real Real.instMonoid))) γ r)
